const filePath = "dsh/.local/root-review/final.txt";
const report: Record<string, unknown> = {};

// 1. write new file
const writeRes = await tools.write({ path: filePath, content: "alpha\nbeta\n" });
report.write = writeRes;

// 2. read it back
let lines = await tools.read({ path: filePath });
const betaLine = lines.find((l) => l.text === "beta");
if (!betaLine) throw new Error("ASSERT FAIL: 'beta' line not found. lines=" + JSON.stringify(lines));
report.betaHash = betaLine.hash;

// 3. edit using that line's hash to replace 'beta' -> 'BETA'
const editRes = await tools.edit({ edits: `=${betaLine.hash}\nBETA` });
report.edit = editRes;

// 4. read back and assert BETA
lines = await tools.read({ path: filePath });
if (!lines.some((l) => l.text === "BETA")) {
  throw new Error("ASSERT FAIL: 'BETA' not present after edit. lines=" + JSON.stringify(lines));
}
report.hashline = true;

// 5. scratch_put
await tools.scratch_put({ key: "final", value: { ok: true } });

// 6. scratch_get + assert
const sg = await tools.scratch_get({ key: "final" });
if (!sg.found) throw new Error("ASSERT FAIL: scratch key 'final' not found");
const v = sg.value;
const okVal =
  v !== null && typeof v === "object" && !Array.isArray(v) &&
  (v as { [k: string]: unknown }).ok === true;
if (!okVal) throw new Error("ASSERT FAIL: scratch value.ok !== true. value=" + JSON.stringify(v));
report.scratch = true;

// 7. skim 7000 y's
const original = "y".repeat(7000);
const skimOut = await tools.skim({ text: original, focus: "count and content" });

// 8. recover ing- ids with pull and assert exactly 7000 y characters
const idMatches = skimOut.match(/ing-[A-Za-z0-9_-]+/g) ?? [];
const ids = Array.from(new Set(idMatches));
const pulls: string[] = [];
for (const id of ids) {
  pulls.push(await tools.pull({ id }));
}
const candidates: string[] = [skimOut, ...pulls, pulls.join("")];
let skimOk = false;
let matchedCandidate = "";
for (const c of candidates) {
  if (c === original) { skimOk = true; matchedCandidate = "exact-original"; break; }
  const yCount = (c.match(/y/g) ?? []).length;
  if (yCount === 7000) { skimOk = true; matchedCandidate = "count-7000"; break; }
}
if (!skimOk) {
  throw new Error(
    "ASSERT FAIL: skim/pull did not yield exactly 7000 y's. ids=" + JSON.stringify(ids) +
    " skimLen=" + skimOut.length + " skimHead=" + JSON.stringify(skimOut.slice(0, 300))
  );
}
report.skim = true;
report.skimIds = ids;
report.skimMatch = matchedCandidate;

// 9. board_send
const boardRes = await tools.board_send({
  topic: "verify/dsh-port-root-review/final",
  body: "DSH_ROOT_FINAL_OK",
});
report.board = true;
report.boardRes = boardRes;

// 10. required compact JSON log after all assertions pass
console.log(JSON.stringify({ hashline: true, scratch: true, skim: true, board: true }));

return report;
